import React, { useState, useEffect } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import ProductCard from '../components/ProductCard';
import ProductModal from '../components/ProductModal';

const Home = () => {
    const { user } = useAuth();
    const [searchParams] = useSearchParams();
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [category, setCategory] = useState('todos');
    const [selectedProduct, setSelectedProduct] = useState(null);
    const [modalOpen, setModalOpen] = useState(false);

    useEffect(() => {
        fetchProducts();
    }, [category, searchParams]);

    // Listener para abrir modal a partir do dashboard do vendedor
    useEffect(() => {
        const handleOpenModal = (event) => {
            console.log('Evento recebido:', event.detail);
            if (event.detail) {
                setSelectedProduct(event.detail);
                setModalOpen(true);
            }
        };
        
        window.addEventListener('openProductModal', handleOpenModal);
        
        return () => {
            window.removeEventListener('openProductModal', handleOpenModal);
        };
    }, []);

    const fetchProducts = async () => {
        setLoading(true);
        try {
            const search = searchParams.get('search') || '';
            const response = await api.get('/products', {
                params: { category: category !== 'todos' ? category : undefined, search, limit: 12 }
            });
            setProducts(response.data.products);
        } catch (error) {
            console.error('Erro ao buscar produtos:', error);
        } finally {
            setLoading(false);
        }
    };

    const openModal = (product) => {
        setSelectedProduct(product);
        setModalOpen(true);
    };

    const closeModal = () => {
        setModalOpen(false);
        setSelectedProduct(null);
    };

    const categories = [
        { id: 'todos', name: 'Todos', icon: '📦' },
        { id: 'telemovel', name: 'Telemóveis', icon: '📱' },
        { id: 'laptop', name: 'Laptops', icon: '💻' },
        { id: 'console', name: 'Consoles', icon: '🎮' },
        { id: 'tablet', name: 'Tablets', icon: '📟' }
    ];

    return (
      // No Home.js, a hero section deve ficar assim:
<div className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl p-8 mb-8 text-center dark:from-gray-800 dark:to-gray-900">
    <h1 className="text-3xl md:text-4xl font-bold mb-4">InterConectados</h1>
    <p className="text-lg md:text-xl mb-6 opacity-90">Conectando pessoas através da tecnologia</p>
    {!user && (
        <div className="flex justify-center gap-4">
            <Link to="/register" className="bg-white text-blue-600 px-6 py-3 rounded-lg font-semibold hover:bg-gray-100 transition dark:bg-gray-800 dark:text-white dark:hover:bg-gray-700">
                Começar a Comprar
            </Link>
            <Link to="/register" className="border-2 border-white text-white px-6 py-3 rounded-lg font-semibold hover:bg-white hover:text-blue-600 transition dark:border-gray-600 dark:hover:bg-gray-800">
                Anunciar Grátis
            </Link>
        </div>
    )}
</div> 
    );
};

export default Home;
